  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\nenum Role {\n  STUDENT\n  FACULTY\n  ADMIN\n}\n\nenum ResourceStatus {\n  AVAILABLE\n  BOOKED\n  MAINTENANCE\n  IN_USE\n}\n\nenum BookingStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n  COMPLETED\n  NO_SHOW\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum IssueStatus {\n  OPEN\n  IN_REPAIR\n  SCHEDULED\n  RESOLVED\n}\n\nenum OpportunityType {\n  HACKATHON\n  INTERNSHIP\n  COMPETITION\n  WORKSHOP\n  SCHOLARSHIP\n  RESEARCH\n}\n\nmodel Department {\n  id        String     @id @default(uuid())\n  code      String     @unique\n  name      String\n  users     User[]\n  resources Resource[]\n  createdAt DateTime   @default(now())\n}\n\nmodel User {\n  id            String           @id @default(uuid())\n  email         String           @unique\n  name          String\n  role          Role             @default(STUDENT)\n  avatar        String?\n  rollNumber    String?\n  departmentId  String?\n  department    Department?      @relation(fields: [departmentId], references: [id])\n  bookings      Booking[]        @relation(\"UserBookings\")\n  approvals     Approval[]       @relation(\"ApproverUser\")\n  checkIns      CheckIn[]\n  waitlists     Waitlist[]\n  issues        Issue[]\n  auditLogs     AuditLog[]\n  projects      Project[]        @relation(\"StudentProjects\")\n  mentoredProjs Project[]        @relation(\"FacultyMentoredProjects\")\n  progress      StudentProgress?\n  notifications Notification[]\n  createdAt     DateTime         @default(now())\n}\n\nmodel Resource {\n  id           String              @id @default(uuid())\n  name         String\n  type         String // Lab, Room, Equipment, Facility\n  building     String\n  floor        String\n  capacity     Int                 @default(1)\n  status       ResourceStatus      @default(AVAILABLE)\n  departmentId String\n  department   Department          @relation(fields: [departmentId], references: [id])\n  imageUrl     String?\n  isShared     Boolean             @default(false)\n  sharedWith   String[] // Array of department codes\n  features     ResourceFeature[]\n  bundleItems  ResourceBundle[]    @relation(\"BundleItems\")\n  bundleParent ResourceBundle[]    @relation(\"ParentBundle\")\n  bookings     BookingResource[]\n  maintenance  MaintenanceWindow[]\n  issues       Issue[]\n  projectReqs  ProjectResource[]\n  createdAt    DateTime            @default(now())\n}\n\nmodel ResourceFeature {\n  id         String   @id @default(uuid())\n  resourceId String\n  resource   Resource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n  feature    String\n}\n\nmodel ResourceBundle {\n  id             String   @id @default(uuid())\n  parentResId    String\n  parentResource Resource @relation(\"ParentBundle\", fields: [parentResId], references: [id])\n  itemResId      String\n  itemResource   Resource @relation(\"BundleItems\", fields: [itemResId], references: [id])\n}\n\nmodel Booking {\n  id          String            @id @default(uuid())\n  bookingCode String            @unique\n  userId      String\n  user        User              @relation(\"UserBookings\", fields: [userId], references: [id])\n  purpose     String\n  startTime   DateTime\n  endTime     DateTime\n  status      BookingStatus     @default(PENDING)\n  resources   BookingResource[]\n  approvals   Approval[]\n  checkIn     CheckIn?\n  waitlist    Waitlist?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n}\n\nmodel BookingResource {\n  id         String   @id @default(uuid())\n  bookingId  String\n  booking    Booking  @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  resourceId String\n  resource   Resource @relation(fields: [resourceId], references: [id])\n}\n\nmodel Approval {\n  id         String        @id @default(uuid())\n  bookingId  String\n  booking    Booking       @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  approverId String\n  approver   User          @relation(\"ApproverUser\", fields: [approverId], references: [id])\n  status     BookingStatus\n  notes      String?\n  createdAt  DateTime      @default(now())\n}\n\nmodel CheckIn {\n  id        String   @id @default(uuid())\n  bookingId String   @unique\n  booking   Booking  @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  scannedAt DateTime @default(now())\n}\n\nmodel Waitlist {\n  id        String   @id @default(uuid())\n  bookingId String   @unique\n  booking   Booking  @relation(fields: [bookingId], references: [id])\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  position  Int\n  createdAt DateTime @default(now())\n}\n\nmodel MaintenanceWindow {\n  id         String   @id @default(uuid())\n  resourceId String\n  resource   Resource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n  reason     String\n  startTime  DateTime\n  endTime    DateTime\n  isResolved Boolean  @default(false)\n}\n\nmodel Issue {\n  id           String      @id @default(uuid())\n  resourceId   String\n  resource     Resource    @relation(fields: [resourceId], references: [id])\n  reportedById String\n  reportedBy   User        @relation(fields: [reportedById], references: [id])\n  description  String\n  priority     Priority    @default(MEDIUM)\n  status       IssueStatus @default(OPEN)\n  createdAt    DateTime    @default(now())\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  message   String\n  type      String // BOOKING, APPROVAL, MAINTENANCE, OPPORTUNITY\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id])\n  userName  String\n  action    String\n  resource  String\n  status    String\n  details   String?\n  timestamp DateTime @default(now())\n}\n\nmodel Project {\n  id          String            @id @default(uuid())\n  title       String\n  description String\n  progress    Int               @default(0)\n  mentorId    String?\n  mentor      User?             @relation(\"FacultyMentoredProjects\", fields: [mentorId], references: [id])\n  students    User[]            @relation(\"StudentProjects\")\n  resources   ProjectResource[]\n  milestones  String[]\n  createdAt   DateTime          @default(now())\n}\n\nmodel ProjectResource {\n  id         String   @id @default(uuid())\n  projectId  String\n  project    Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  resourceId String\n  resource   Resource @relation(fields: [resourceId], references: [id])\n}\n\nmodel Opportunity {\n  id           String          @id @default(uuid())\n  title        String\n  organization String\n  type         OpportunityType\n  deadline     DateTime\n  tags         String[]\n  location     String?\n  description  String\n  applyUrl     String?\n  createdAt    DateTime        @default(now())\n}\n\nmodel StudentProgress {\n  id                  String @id @default(uuid())\n  userId              String @unique\n  user                User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  overallReadiness    Int    @default(72)\n  dsaScore            Int    @default(70)\n  aptitudeScore       Int    @default(80)\n  csFundamentalsScore Int    @default(60)\n  projectsScore       Int    @default(85)\n  communicationScore  Int    @default(70)\n}\n",
